  { id: 'q109', difficulty: 10, category: 'Storia', question: 'Quale trattato del 1648 pose fine alla Guerra dei Trent\'anni?', answers: ['Pace di Utrecht', 'Pace di Vestfalia', 'Pace di Augusta', 'Pace di Nimega'], correctAnswerIndex: 1, explanation: 'La Pace di Vestfalia ridisegnò gli equilibri politici e religiosi europei.', hint: 'Ridisegnò gli equilibri politici e religiosi europei nel Seicento.' },
  { id: 'q110', difficulty: 10, category: 'Scienza', question: 'Come si chiama l\'equazione fondamentale che descrive l\'evoluzione temporale della funzione d\'onda in meccanica quantistica?', answers: ['Equazione di Dirac', 'Equazione di Schrödinger', 'Equazione di Klein-Gordon', 'Equazione di Maxwell'], correctAnswerIndex: 1, explanation: 'Erwin Schrödinger la formulò nel 1925.', hint: 'Lo stesso fisico è noto anche per un celebre paradosso con un gatto.' },
  { id: 'q111', difficulty: 10, category: 'Letteratura', question: 'Chi scrisse il monumentale e incompiuto romanzo "L\'uomo senza qualità"?', answers: ['Thomas Mann', 'Robert Musil', 'Hermann Broch', 'Franz Kafka'], correctAnswerIndex: 1, explanation: 'Musil vi lavorò per gran parte della sua vita senza terminarlo.', hint: 'Scrittore austriaco, vi lavorò per gran parte della sua vita senza terminarlo.' },
  { id: 'q112', difficulty: 10, category: 'Geografia', question: 'Quale fiume europeo attraversa quattro capitali nazionali lungo il suo corso?', answers: ['Reno', 'Danubio', 'Volga', 'Elba'], correctAnswerIndex: 1, explanation: 'Il Danubio bagna Vienna, Bratislava, Budapest e Belgrado.', hint: 'Bagna Vienna, Bratislava, Budapest e Belgrado.' },
  { id: 'q113', difficulty: 10, category: 'Musica', question: 'Quale compositore lasciò incompiuta, alla morte, l\'opera contrappuntistica "L\'arte della fuga"?', answers: ['Georg Philipp Telemann', 'Johann Sebastian Bach', 'Dietrich Buxtehude', 'Heinrich Schütz'], correctAnswerIndex: 1, explanation: 'Bach lavorò all\'opera fino agli ultimi anni di vita, morendo nel 1750.', hint: 'Compositore tedesco del periodo barocco, morto nel 1750.' },
  { id: 'q115', difficulty: 10, category: 'Mitologia', question: 'Nella mitologia norrena, come si chiama la nave costruita con le unghie dei morti, che salperà durante il Ragnarök?', answers: ['Skidbladnir', 'Naglfar', 'Hringhorni', 'Draupnir'], correctAnswerIndex: 1, explanation: 'Naglfar è descritta nell\'Edda in prosa come la nave dei giganti e dei morti.', hint: 'È descritta nell\'Edda in prosa come la nave dei giganti e dei morti.' },
  { id: 'q117', difficulty: 10, category: 'Storia', question: 'Chi fu l\'ultimo Sacro Romano Imperatore, che sciolse formalmente l\'impero nel 1806?', answers: ['Giuseppe II', 'Leopoldo II', 'Francesco II d\'Asburgo-Lorena', 'Ferdinando I'], correctAnswerIndex: 2, explanation: 'Francesco II abdicò come imperatore del Sacro Romano Impero sotto la pressione napoleonica, restando imperatore d\'Austria.', hint: 'Abdicò sotto la pressione napoleonica, restando comunque imperatore d\'Austria.' },
  { id: 'q118', difficulty: 10, category: 'Arte', question: 'Chi scrisse il trattato rinascimentale "De Pictura", fondamentale per la teoria della prospettiva?', answers: ['Filippo Brunelleschi', 'Leon Battista Alberti', 'Piero della Francesca', 'Lorenzo Ghiberti'], correctAnswerIndex: 1, explanation: 'Alberti lo scrisse nel 1435, codificando le regole della prospettiva lineare.', hint: 'Umanista e architetto rinascimentale, scrisse anche il "De Re Aedificatoria".' },
  { id: 'q119', difficulty: 10, category: 'Letteratura', question: 'Chi scrisse il trattato filosofico "Critica della ragion pura"?', answers: ['Georg Wilhelm Friedrich Hegel', 'Immanuel Kant', 'Arthur Schopenhauer', 'Johann Gottlieb Fichte'], correctAnswerIndex: 1, explanation: 'Kant lo pubblicò nel 1781, opera cardine della filosofia moderna.', hint: 'Filosofo di Königsberg, non uscì praticamente mai dalla sua città natale.' },
  { id: 'q120', difficulty: 10, category: 'Scienza', question: 'Come si chiama il teorema secondo cui, in ogni sistema formale coerente sufficientemente potente, esistono proposizioni indecidibili?', answers: ['Teorema di Church', 'Teorema di incompletezza di Gödel', 'Teorema di Tarski', 'Teorema di Turing'], correctAnswerIndex: 1, explanation: 'Kurt Gödel lo dimostrò nel 1931, con conseguenze fondamentali per la logica matematica.', hint: 'Il matematico austriaco che lo dimostrò nel 1931 dà il nome al teorema.' },
  { id: 'q228', difficulty: 10, category: 'Scienza', question: 'Quanti elementi conta la tavola periodica, dopo i nomi ufficiali assegnati nel 2016?', answers: ['118', '112', '116', '122'], correctAnswerIndex: 0, explanation: 'Nel 2016 la IUPAC ha battezzato gli ultimi quattro: nihonio, moscovio, tennesso e oganesson, che chiude la tavola.', hint: 'Con quei nomi il settimo periodo della tavola è diventato completo.' },
  { id: 'q229', difficulty: 10, category: 'Storia', question: 'In quale città trasferì la capitale dell\'Impero d\'Occidente l\'imperatore Onorio, nel 402?', answers: ['Milano', 'Treviri', 'Ravenna', 'Aquileia'], correctAnswerIndex: 2, explanation: 'Onorio lasciò Milano per Ravenna, protetta dalle paludi e vicina al porto di Classe.', hint: 'Oggi è famosa per i suoi mosaici bizantini.' },
  { id: 'q230', difficulty: 10, category: 'Geografia', question: 'Qual è il paese più grande del mondo senza sbocco sul mare?', answers: ['Mongolia', 'Kazakistan', 'Bolivia', 'Ciad'], correctAnswerIndex: 1, explanation: 'Il Kazakistan è il nono paese al mondo per superficie; il Mar Caspio che bagna le sue coste è in realtà un lago.', hint: 'Ospita il cosmodromo di Bajkonur.' },
  { id: 'q231', difficulty: 10, category: 'Arte', question: 'Chi dipinse "La zattera della Medusa" (1819), ispirata a un naufragio reale?', answers: ['Eugène Delacroix', 'Jacques-Louis David', 'Gustave Courbet', 'Théodore Géricault'], correctAnswerIndex: 3, explanation: 'Géricault intervistò i sopravvissuti e studiò cadaveri negli obitori per rendere la scena il più vera possibile.', hint: 'Morì a 32 anni, dopo una serie di cadute da cavallo.' },
  { id: 'q232', difficulty: 10, category: 'Letteratura', question: '"Italo Svevo" era lo pseudonimo di quale scrittore?', answers: ['Ettore Schmitz', 'Dino Segre', 'Kurt Erich Suckert', 'Alberto Pincherle'], correctAnswerIndex: 0, explanation: 'Ettore Schmitz scelse "Italo Svevo" per unire radici italiane e tedesche. Gli altri sono i veri nomi di Pitigrilli, Malaparte e Moravia.', hint: 'Era un triestino che lavorava nell\'azienda di vernici del suocero.' },
  { id: 'q233', difficulty: 10, category: 'Musica', question: 'Chi compose l\'opera "Wozzeck" (1925)?', answers: ['Arnold Schönberg', 'Alban Berg', 'Anton Webern', 'Richard Strauss'], correctAnswerIndex: 1, explanation: 'Berg la trasse dal dramma "Woyzeck" di Georg Büchner: è uno dei capolavori dell\'opera del Novecento.', hint: 'Fu allievo di Schönberg, come Anton Webern.' },
  { id: 'q234', difficulty: 10, category: 'Logica', question: 'Quante diagonali ha un ottagono?', answers: ['16', '20', '24', '28'], correctAnswerIndex: 1, explanation: 'La formula è n × (n − 3) / 2: con otto lati fa 8 × 5 / 2 = 20.', hint: 'Da ogni vertice ne partono cinque.' },
  { id: 'q235', difficulty: 10, category: 'Internet', question: 'Chi inviò, nel 1971, la prima email tra due computer in rete, scegliendo il simbolo "@"?', answers: ['Vint Cerf', 'Bob Kahn', 'Ray Tomlinson', 'Larry Roberts'], correctAnswerIndex: 2, explanation: 'Ray Tomlinson usò la chiocciola per separare il nome dell\'utente da quello del computer; il testo del primo messaggio non se lo ricordava nemmeno lui.', hint: 'Lavorava alla BBN, un\'azienda che sviluppava ARPANET.' },
  { id: 'q236', difficulty: 10, category: 'Mitologia', question: 'Come si chiama il cavallo a otto zampe di Odino?', answers: ['Gullfaxi', 'Grani', 'Skinfaxi', 'Sleipnir'], correctAnswerIndex: 3, explanation: 'Sleipnir è il migliore dei cavalli secondo l\'Edda: Hermóðr lo cavalcò fino al regno dei morti.', hint: 'Sua "madre" era Loki, trasformato in giumenta.' },
  { id: 'q237', difficulty: 10, category: 'Cinema', question: 'Quale fu il primo film a colori a vincere l\'Oscar come miglior film?', answers: ['Il mago di Oz', 'Via col vento', 'Rebecca', 'Ben-Hur'], correctAnswerIndex: 1, explanation: '"Via col vento" (1939) vinse otto Oscar competitivi, tra cui quello a Hattie McDaniel, la prima persona afroamericana premiata.', hint: 'Uscì nel 1939, tratto dal romanzo di Margaret Mitchell.' },
  { id: 'q238', difficulty: 10, category: 'Natura', question: 'Oltre all\'ornitorinco, quale altro mammifero depone le uova?', answers: ['Il tenrec', 'L\'echidna', 'L\'opossum', 'Il pangolino'], correctAnswerIndex: 1, explanation: 'Ornitorinco ed echidne sono i monotremi: mammiferi che depongono uova ma poi allattano i piccoli.', hint: 'Sembra un porcospino e vive in Australia e Nuova Guinea.' },
  { id: 'q239', difficulty: 10, category: 'Calcio', question: 'Chi vinse la prima Coppa dei Campioni, nel 1956?', answers: ['Milan', 'Benfica', 'Stade de Reims', 'Real Madrid'], correctAnswerIndex: 3, explanation: 'Il Real Madrid batté lo Stade de Reims 4-3 a Parigi, e vinse anche le quattro edizioni successive.', hint: 'Gioca le partite in casa al Santiago Bernabéu.' },
  { id: 'q240', difficulty: 10, category: 'Tecnologia', question: 'Come si chiamava il primo computer elettronico general purpose, presentato nel 1946?', answers: ['ENIAC', 'UNIVAC', 'Colossus', 'Z3'], correctAnswerIndex: 0, explanation: 'L\'ENIAC pesava circa 27 tonnellate e usava quasi 18.000 valvole termoioniche.', hint: 'Fu costruito all\'Università della Pennsylvania per calcolare traiettorie di artiglieria.' },
  { id: 'q241', difficulty: 10, category: 'Geografia', question: 'Qual è la vetta più alta degli Appennini?', answers: ['Monte Vettore', 'Monte Amaro', 'Monte Cimone', 'Corno Grande'], correctAnswerIndex: 3, explanation: 'Il Corno Grande, nel massiccio del Gran Sasso d\'Italia, raggiunge 2.912 metri.', hint: 'Si trova in Abruzzo, nel massiccio del Gran Sasso.' }
